const STORAGE='genehub-team-ui-prototype-v3';
const defaults=()=>({machine:'studio',section:'sessions',sid:'pm',space:'camp',showDetail:true,tab:'flow',filter:'all',query:'',expanded:['camp','camp-exec'],drafts:{},messages:{},extra:[],decision:null,resourceFeedback:{},scene:'night',character:50,scroll:{},offline:false,offlinePhase:null,blocked:false,questionAnswer:null,runId:'015'});
function restore(){
  const base=defaults();
  try {
    const old=JSON.parse(localStorage.getItem(STORAGE)||'null');
    if(!old||old.version!==3)return base;
    const s={...base};
    if(['studio','laptop'].includes(old.machine))s.machine=old.machine;
    if(['sessions','inbox','spaces'].includes(old.section))s.section=old.section;
    if(BASE_SESSIONS.some(x=>x.id===old.sid))s.sid=old.sid;
    if(BASE_SPACES.some(x=>x.id===old.space))s.space=old.space;
    s.showDetail=old.showDetail!==false;
    if(['flow','artifacts','team','project'].includes(old.tab))s.tab=old.tab;
    if(old.drafts&&typeof old.drafts==='object'){
      s.drafts=Object.fromEntries(Object.entries(old.drafts).filter(([k,v])=>/^[a-z0-9-]+$/.test(k)&&typeof v==='string').slice(-20).map(([k,v])=>[k,v.slice(0,4000)]));
    }
    if(old.messages&&typeof old.messages==='object'){
      s.messages=Object.fromEntries(Object.entries(old.messages).filter(([k,v])=>/^[a-z0-9-]+$/.test(k)&&Array.isArray(v)).slice(-20).map(([k,v])=>[k,v.filter(x=>typeof x==='string').slice(-12).map(x=>x.slice(0,4000))]));
    }
    if(Array.isArray(old.extra))s.extra=old.extra.filter(x=>x&&/^draft-[0-9]+$/.test(x.id)&&BASE_SPACES.some(w=>w.id===x.space)).slice(-12).map(x=>({id:x.id,space:x.space,title:String(x.title||'新会话').slice(0,100),agent:['Genet','Codex','Cursor','Claude Code'].includes(x.agent)?x.agent:'Genet',role:'',kind:'normal',mark:'N',status:(s.messages[x.id]||[]).length?'idle':'draft',age:'刚刚',snippet:String(x.snippet||'').slice(0,100),managed:false,updatedAtMs:Number.isFinite(x.updatedAtMs)?x.updatedAtMs:Number(x.id.slice(6))}));
    if(s.extra.some(x=>x.id===old.sid))s.sid=old.sid;
    if(old.decision&&['approved','rejected','expired'].includes(old.decision.value)&&Number.isFinite(old.decision.at))s.decision={value:old.decision.value,at:old.decision.at};
    if(old.scroll&&typeof old.scroll==='object')s.scroll=Object.fromEntries(Object.entries(old.scroll).filter(([k,v])=>/^[a-z0-9/-]+$/.test(k)&&Number.isFinite(v)&&v>=0&&v<1e7).slice(-60));
    for(const key of ['resourceFeedback'])if(old[key]&&typeof old[key]==='object')s[key]=Object.fromEntries(Object.entries(old[key]).filter(([k,v])=>/^[a-z-]+$/.test(k)&&typeof v==='string').slice(0,20).map(([k,v])=>[k,v.slice(0,2000)]));
    if(['theme','time'].includes(old.questionAnswer))s.questionAnswer=old.questionAnswer;
    if(['014','015'].includes(old.runId))s.runId=old.runId;
    s.scene=old.scene==='day'?'day':'night';
    // A corrupt route must never pair another machine's Session with this one.
    const owned=[...BASE_SESSIONS,...s.extra].find(x=>x.id===s.sid);
    if(!owned||BASE_SPACES.find(w=>w.id===owned.space)?.machine!==s.machine){s.sid=s.machine==='studio'?'pm':'travel';s.space=s.machine==='studio'?'camp':'travel';}
    return s;
  }catch{return base;}
}
