function projectView(){
  const flow=currentFlow(),run=flow.run;
  return `<div class="section-pad"><div class="section-eyebrow">执行概览 / 当前项目</div><div class="view-heading"><div><h2>${run.status==='completed'?'已完成一次交付':'当前执行到哪一步'}</h2><p class="section-lead">查看当前节点、执行会话和返回的结果。</p></div>${badge(flowStatus(run.status),run.status==='completed'?'gray':'wait')}</div>${runPicker()}<div class="run-facts-bar"><span>Run ${run.id} · ${run.workflowId}</span><span>最近读取 ${state.offline?'前 · 未同步':'10:28'}</span></div>${viewFailed?'<div class="note" role="alert">暂时无法更新，下面保留上次读取的记录。可以重试或打开原执行会话。</div>':''}<section class="project-canvas native-overview" aria-label="现有运行数据概览"><header><small>RUN / ${run.id}</small><h3>${run.status==='completed'?'一个可以继续生长的营地':'昼夜循环与触屏验收'}</h3><p>${run.status==='completed'?'两个节点均已返回结果。':state.blocked?'验收受阻，查看节点中的原因和证据。':'实现完成；验收节点仍在运行。'}</p></header><div class="view-nodes">${run.nodes.map(n=>`<article><div>${badge(flowStatus(n.status),n.status==='running'?'wait':n.status==='blocked'?'red':'gray')}<span>${escapeHTML(n.uses)}</span></div><h3>${escapeHTML(n.id)}</h3>${n.sessionId?`<button data-action="session" data-id="${n.sessionId}">查看工作会话 ${icon('arrow',13)}</button>`:'<p>本页演示中未装载该历史会话。</p>'}${nodeEvidence(n)}</article>`).join('')}</div></section><div class="view-controls"><button data-action="native-flow">${icon('flow',14)} 打开执行信息流</button><button data-action="run-refresh" ${state.offline?'disabled':''}>刷新</button></div><div class="report-link"><div>${icon('file',22)}<span><strong>工作流说明 · HTML</strong><small>一份可由 WorkflowManager 修改的项目文件</small></span></div><button data-action="report">打开说明页 ${icon('arrow',14)}</button></div><details class="evidence"><summary>运行来源与版本</summary><pre>${escapeHTML(JSON.stringify({runId:run.id,executorSessionId:run.executorSessionId,dcgDigest:run.dcgDigest,revision:run.revision},null,2))}</pre><p>概览与执行信息流读取同一份 session.flow。HTML 说明页是另一个普通文件，不属于 Run 的固定快照。</p></details><button class="demo-text" data-action="view-failure">${viewFailed?'恢复读取示例':'模拟读取失败'}</button></div>`;
}


// All values below are demo responses shaped from existing protocol records.
